\dcref{ch2:3.9}
\label{topping:variation-scalar-curvature}
\source{topping:page-0032,topping:page-0033,topping:page-0037}
\group{topping-background}

\[
\frac{\partial R}{\partial t}=-\langle h,\Ric\rangle+\delta^2h-\Delta(\tr h).
\]
\end{proposition}

